package com.citacloud.springboot.contacloud.app.services;import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.time.*;import java.util.UUID;
@Service public class AjusteInventarioDocumentoService{private final AjusteInventarioRepository ajustes;private final LineaAjusteInventarioRepository lineas;private final EmpresaRepository empresas;private final DatosEmpresaRepository datos;private final UsuarioRepository usuarios;private final LocalFileStorageService storage;private final AjusteInventarioPdfService pdf;public AjusteInventarioDocumentoService(AjusteInventarioRepository a,LineaAjusteInventarioRepository l,EmpresaRepository e,DatosEmpresaRepository d,UsuarioRepository u,LocalFileStorageService s,AjusteInventarioPdfService p){ajustes=a;lineas=l;empresas=e;datos=d;usuarios=u;storage=s;pdf=p;}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)@PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.ver') and hasAuthority('inventario_ajustes.pdf')")public ArchivoPdfDto generar(UUID id){var p=TenantContext.principalActual();AjusteInventario a=ajustes.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Ajuste no encontrado."));if(!EmpresaContext.permiteSucursal(a.getAlmacen().getSucursalId()))throw new ReglaNegocioException("No tienes acceso al almacén de este ajuste.");if(a.getEstado()!=EstadoAjusteInventario.CONFIRMED&&a.getEstado()!=EstadoAjusteInventario.REVERSED)throw new ReglaNegocioException("El PDF oficial solo está disponible para ajustes confirmados o revertidos.");Empresa e=empresas.findByIdAndTenantId(p.empresaId(),p.tenantId()).orElseThrow(()->new ReglaNegocioException("No fue posible identificar la empresa del documento."));DatosEmpresa d=datos.findByEmpresaId(p.empresaId()).orElse(null);Usuario u=usuarios.findByIdAndTenantId(p.usuarioId(),p.tenantId()).orElseThrow(()->new ReglaNegocioException("No fue posible identificar al usuario."));ZoneId z=zone(e.getZonaHoraria());byte[] logo=e.getLogoObjectKey()==null?null:storage.load(e.getLogoObjectKey(),5L*1024*1024).orElse(null);var ls=lineas.findAllByAjusteIdOrderByOrden(id).stream().map(l->new AjusteInventarioReporteData.Linea(l.getOrden(),l.getNombreProducto(),l.getUnidad(),MovimientoInventarioReporteService.number(l.getSaldoAnterior()),signed(l.getCantidadAjuste()),MovimientoInventarioReporteService.number(l.getSaldoPosterior()))).toList();AjusteInventarioReporteData r=new AjusteInventarioReporteData(d==null?e.getNombre():first(d.getNombreComercial(),e.getNombre()),d==null?e.getNombre():first(d.getRazonSocial(),e.getNombre()),e.getIdentificacionFiscal(),d==null?null:d.getDireccion(),d==null?null:d.getTelefono(),d==null?null:d.getCorreo(),logo,a.getNumero(),a.getEstado().getEtiqueta(),a.getFecha(),first(a.getAlmacenHistorico(),a.getAlmacen().getNombre()),first(a.getSucursalHistorica(),a.getAlmacen().getSucursal().getNombre()),first(a.getMotivoHistorico(),a.getMotivo().getNombre()),a.getReferencia(),a.getObservacion(),a.getConfirmadaEn(),actor(a.getConfirmadaPorNombre(),a.getConfirmadaPor(),p.tenantId()),PurchaseOrderService.issuedByDisplayName(u),OffsetDateTime.now(z),ls);return new ArchivoPdfDto("Ajuste_"+a.getNumero()+".pdf",pdf.generar(r,z));}
 private String actor(String s,UUID id,UUID t){if(s!=null&&!s.isBlank())return s;return id==null?null:usuarios.findByIdAndTenantId(id,t).map(PurchaseOrderService::issuedByDisplayName).orElse(null);}private static String signed(java.math.BigDecimal n){if(n==null)return "—";String x=MovimientoInventarioReporteService.number(n.abs());return n.signum()>0?"+"+x:"-"+x;}private static ZoneId zone(String x){try{return ZoneId.of(first(x,"America/Santo_Domingo"));}catch(DateTimeException e){return ZoneId.of("America/Santo_Domingo");}}private static String first(String x,String f){return x==null||x.isBlank()?f:x.trim();}}
